## Code Example

```javascript
// Skeleton: window state store and onEvent flow
class WindowAggregator {
  constructor(windowMs, watermarkMs) { /* init stores */ }
  onEvent(e) {
    // e = {tenantId, userId, ts, value}
    const ws = Math.floor(e.ts / this.windowMs) * this.windowMs;
    const key = `${e.tenantId}:${e.userId}:${ws}`;
    let bucket = this.state.get(key) || {sum: 0, count: 0, maxTs: 0};
    bucket.sum += e.value;
    bucket.count += 1;
    bucket.maxTs = Math.max(bucket.maxTs, e.ts);
    this.state.set(key, bucket);
    // emit when window closes or on a timer
  }
}
```

